/bin/bash -lc 'ls -la && npm test; test_status=$?; npm run lint; lint_status=$?; npm run build; build_status=$?; node --input-type=module - <<'"'EOF'
import { discountMinor } from './src/discount.js';
const cases = [
  ['negative subtotal', -1, 2026],
  ['zero subtotal', 0, 2026],
  ['fractional subtotal', 10000.5, 2026],
  ['string subtotal', '10000', 2026],
  ['NaN subtotal', NaN, 2026],
  ['future member year', 10000, 2030],
  ['missing member year', 10000, undefined],
  ['string member year', 10000, '2021'],
  ['fractional member year', 10000, 2021.5],
];
for (const [name, subtotal, memberSince] of cases) {
  try { console.log(name, '=>', discountMinor(subtotal, memberSince)); }
  catch (e) { console.log(name, 'THREW', e.name, e.message); }
}
EOF
exit 0"

